import {TOPICS, QUESTIONS, LOGIC, VOCAB, OBSTACLE, MODE_INFO} from './data.js';
import {isOnlineConfigured, createRoom, joinRoom, identity, subscribe, nextQuestion, pressBuzzer, decide, showAnswer} from './online.js';

const $ = sel => document.querySelector(sel);
const icon = (name, cl='') => `<svg class="icon ${cl}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc = v => String(v??'').replace(/[&<>"']/g, ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const number = n => new Intl.NumberFormat('vi-VN').format(Number(n)||0);
const norm = v => String(v??'').toLocaleLowerCase('vi').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9]/g,'');
const same = (answer,q) => (q.answers||[q.answer]).some(x => norm(x)===norm(answer));
const shuffle = arr => [...arr].sort(()=>Math.random()-.5);
const levelFor = xp => Math.floor(Math.sqrt(Math.max(0,xp)/120))+1;
const levelStart = level => 120*(level-1)**2;
const levelEnd = level => 120*level**2;
const today = () => new Date().toLocaleDateString('en-CA');
const dateLabel = time => new Date(time).toLocaleDateString('vi-VN',{day:'2-digit',month:'2-digit',year:'numeric'});
const mode = key => MODE_INFO[key]||MODE_INFO.marathon;
const titleFor = route => ({home:'Tổng quan',play:'Đấu trường',library:'Ngân hàng câu hỏi',records:'Thành tích',classroom:'Phòng thi lớp học',online:'Thi trực tuyến',settings:'Cài đặt',game:'Đang thi'})[route.split('/')[0]] || 'Đấu trường';
const STORAGE = 'dinh-tri-thuc-v1';
const freshProfile = () => ({name:'Nhà chinh phục',xp:0,history:[],custom:[],streak:0,lastPlay:'',settings:{sound:true,reduceMotion:false},classroom:null});
let profile;
try { profile = {...freshProfile(),...JSON.parse(localStorage.getItem(STORAGE)||'{}')}; } catch { profile = freshProfile(); }
if (!Array.isArray(profile.history)) profile.history=[];
if (!Array.isArray(profile.custom)) profile.custom=[];
profile.settings={...freshProfile().settings,...profile.settings};
let game=null;
let quizInterval=null,roomUnsub=null,roomCode='',roomState=null,onlineLoading=false,roomError='';
let classInterval=null;
let mobileOpen=false;
let currentModal='';
let filter={text:'',topic:'all',type:'all',page:0};
let marathonTopic='all';
let toastTimeout=null;
let audioCtx=null;
const root=$('#app');
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify(profile));}catch{toast('Không thể lưu dữ liệu vào bộ nhớ trình duyệt.',true);}}
function notifySound(success=true){
 if(!profile.settings.sound)return;
 try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioCtx ||= new AC();if(audioCtx.state==='suspended')audioCtx.resume(); const now=audioCtx.currentTime;
 [0,.09].forEach((d,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.setValueAtTime((success?660:240)+(success?i*180:-i*60),now+d);gain.gain.setValueAtTime(.04,now+d);gain.gain.exponentialRampToValueAtTime(.001,now+d+.13);osc.connect(gain).connect(audioCtx.destination);osc.start(now+d);osc.stop(now+d+.15);});}catch{}
}
function toast(message,error=false){const el=$('#toast');if(!el)return;el.innerHTML=`<div class="toast-msg ${error?'error':''}">${esc(message)}</div>`;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>{if(el)el.innerHTML='';},3200);}
function celebrate(){if(profile.settings.reduceMotion)return;const el=$('#confetti');el.innerHTML=Array.from({length:70},(_,i)=>`<i class="confetti-piece" style="left:${Math.random()*100}%;background:${['#cbfa79','#ffce7f','#9abfff','#c9a9ff'][i%4]};animation-delay:${Math.random()*.8}s;animation-duration:${1.7+Math.random()*1.8}s;transform:rotate(${Math.random()*90}deg)"></i>`).join('');setTimeout(()=>el.innerHTML='',3900);}
function bank(){return [...profile.custom,...QUESTIONS,...LOGIC,...VOCAB];}
function route(){return (location.hash.replace(/^#\/?/,'')||'home').split('?')[0];}
function navigate(path){mobileOpen=false;const newHash='#/'+path;if(location.hash!==newHash)location.hash=newHash;else render();window.scrollTo({top:0,behavior:profile.settings.reduceMotion?'instant':'smooth'});}
function navLink(path,label,ico){const r=route();return `<button class="nav-btn ${r===path || (path==='play'&&(r.startsWith('mode/')||r==='game'))?'active':''}" data-action="nav" data-path="${path}">${icon(ico)}<span>${label}</span></button>`;}
function shell(content){const r=route(),lv=levelFor(profile.xp),initial=esc(profile.name.trim().slice(0,1).toLocaleUpperCase('vi')||'N');
 root.innerHTML=`<div class="layout ${mobileOpen?'menu-open':''}"><div class="app-shade" data-action="close-menu"></div><aside class="sidebar"><a href="#/home" class="brand" aria-label="Về trang chủ"><div class="brand-mark">${icon('mountain')}</div><div><div class="brand-name">đỉnh tri thức.</div><div class="brand-caption">LEARN · PLAY · CONQUER</div></div></a>
 <div class="nav-label">KHÁM PHÁ</div><nav class="nav-list" aria-label="Điều hướng chính">${navLink('home','Trang chủ','grid')}${navLink('play','Chế độ chơi','compass')}${navLink('classroom','Thi đấu lớp học','users')}${navLink('online','Phòng thi online','wifi')}</nav>
 <div class="nav-divider"></div><div class="nav-label">HỌC TẬP</div><nav class="nav-list">${navLink('library','Kho câu hỏi','book')}${navLink('records','Thành tích của tôi','trophy')}${navLink('settings','Cài đặt','settings')}</nav><div class="sidebar-spacer"></div>
 <div class="side-challenge"><div class="side-kicker">THỬ THÁCH HÔM NAY</div><strong>60 giây bứt phá.</strong><p>Đồng hồ đang chờ. Bạn đã sẵn sàng?</p><button data-action="start" data-mode="marathon">Chơi Marathon ${icon('arrow','sm')}</button></div>
 <div class="side-profile"><div class="avatar">${initial}</div><div><strong>${esc(profile.name)}</strong><span>Cấp ${lv} · ${number(profile.xp)} XP</span></div><button class="icon-btn push" style="height:31px;width:31px" title="Cài đặt" data-action="nav" data-path="settings">${icon('settings','sm')}</button></div><div class="side-footer">© 2026 Đỉnh Tri Thức · V1.0</div></aside>
 <div class="content"><header class="topbar"><div class="flex"><button class="icon-btn menu-btn" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="crumb"><span>ĐỈNH TRI THỨC</span>${icon('chevron','sm')}<span class="current">${esc(r.startsWith('mode/')?mode(r.split('/')[1]).title:titleFor(r))}</span></div></div><div class="top-actions"><button class="search-trigger" data-action="search">${icon('search','sm')}<span>Tìm câu hỏi...</span><span class="kbd">/</span></button><button class="icon-btn" data-action="sound" title="${profile.settings.sound?'Tắt':'Bật'} âm thanh">${icon(profile.settings.sound?'volume':'mute')}</button><button class="icon-btn" data-action="fullscreen" title="Toàn màn hình">${icon('target')}</button><div class="avatar top-avatar">${initial}</div></div></header><main class="page">${content}</main></div></div>`;
}
function art(){return `<div class="mountain-art" aria-hidden="true"><svg viewBox="0 0 610 320" preserveAspectRatio="xMidYMax meet"><defs><linearGradient id="mountain-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c5f78a" stop-opacity=".35"/><stop offset="1" stop-color="#3c8555" stop-opacity="0"/></linearGradient><linearGradient id="mountain-stroke" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#9ce17a" stop-opacity="0"/><stop offset=".6" stop-color="#d8ff9e"/><stop offset="1" stop-color="#d6ff96" stop-opacity=".8"/></linearGradient></defs><g opacity=".22" fill="none" stroke="#b7f1a8" stroke-width=".7">${Array.from({length:8},(_,i)=>`<path d="M0 ${110+i*24} Q230 ${-50+i*25} 610 ${100+i*15}"/>`).join('')}${Array.from({length:8},(_,i)=>`<circle cx="${70+i*68}" cy="${26+i%3*18}" r="${i%2+1}" fill="#d6ffae" stroke="none"/>`).join('')}</g><path d="M9 315 130 231l63 43 95-182 39 65 42-76 72 95 54-55 113 194Z" fill="url(#mountain-fill)"/><path d="M9 315 130 231l63 43 95-182 39 65 42-76 72 95 54-55 113 194" fill="none" stroke="url(#mountain-stroke)" stroke-width="2.5"/><path d="m236 205 52-113 39 65 42-76 51 67" fill="none" stroke="#e5ffc5" opacity=".4"/><path d="M205 315q90-45 140-60t95-5q70 10 125-50" fill="none" stroke="#c9ff8d" stroke-width="1.5" stroke-dasharray="7 8" opacity=".75"/><circle cx="288" cy="92" r="8" fill="#c7ff80"/><circle cx="288" cy="92" r="20" fill="none" stroke="#c7ff80" opacity=".24"/><path d="m277 88 11-15 11 15" fill="none" stroke="#c7ff80"/><text x="301" y="69" fill="#e6ffd2" font-size="11" font-family="sans-serif" letter-spacing="2">SUMMIT</text><path d="M0 315h610" stroke="#c7ff80" opacity=".5"/></svg></div>`;}
function stat(label,value,note,ico){return `<div class="stat"><div class="stat-label">${label}</div><div class="stat-value num">${value}</div><div class="stat-note">${note}</div><div class="stat-icon">${icon(ico)}</div></div>`;}
function modeCard(id,featured=false){const m=mode(id);return `<button class="mode-card ${m.color} ${featured?'featured':''}" data-action="nav" data-path="mode/${id}"><div class="mode-ornament"></div><div class="mode-icon">${icon(m.icon)}</div><h3>${m.title}</h3><p>${m.subtitle}</p><div class="mode-foot"><span>${icon('clock','sm')} &nbsp; ${m.time}</span>${icon('arrow','sm')}</div></button>`;}
function homePage(){const games=profile.history.length,lv=levelFor(profile.xp),correct=profile.history.reduce((s,h)=>s+h.correct,0),total=profile.history.reduce((s,h)=>s+h.total,0);const accuracy=total?Math.round(correct/total*100):0;const modeIds=['olympia','marathon','hurdling','math','logic','vocab','duel'];
 const recent=profile.history.slice(0,4).map(h=>`<div class="activity"><div class="activity-icon">${icon(mode(h.mode).icon,'sm')}</div><div class="activity-main"><strong>${esc(mode(h.mode).title)}</strong><span>${dateLabel(h.date)} · ${h.correct}/${h.total} câu đúng</span></div><span class="activity-points">+${number(h.xp)} XP</span></div>`).join('');
 const bestByName=Object.entries(profile.history.reduce((o,h)=>{o[h.name]=Math.max(o[h.name]||0,h.score);return o;},{})).sort((a,b)=>b[1]-a[1]).slice(0,5);
 return `<div class="hero"><div class="hero-copy"><div class="hero-kicker"><i class="live-dot"></i> KHÁM PHÁ · BỨT PHÁ · CHINH PHỤC</div><h1>Giới hạn duy nhất<br>là <em>đỉnh cao tiếp theo.</em></h1><p>Mỗi câu hỏi là một bước tiến. Rèn phản xạ, mở rộng kiến thức và chinh phục những thử thách của riêng bạn.</p><div class="hero-actions"><button class="btn primary" data-action="nav" data-path="mode/olympia">Bắt đầu hành trình ${icon('arrow','sm')}</button><button class="btn dark" data-action="nav" data-path="play">Khám phá chế độ</button></div></div><div class="hero-badge">◆ YOUR SUMMIT AWAITS</div>${art()}</div>
 <div class="stats">${stat('Tổng điểm kinh nghiệm',number(profile.xp),'Cấp '+lv+' · Nhà chinh phục','bolt')}${stat('Số lượt chinh phục',number(games),'Các lượt đã hoàn thành','trophy')}${stat('Độ chính xác',accuracy+'%','Dựa trên các lượt đã chơi','target')}${stat('Chuỗi ngày học',number(profile.streak),'Ngày học liên tiếp','zap')}</div>
 <div class="section-head"><div><h2>Chọn sân chơi của bạn</h2><p>7 trải nghiệm được thiết kế để rèn trí tuệ.</p></div><button class="text-link" data-action="nav" data-path="play">Tất cả chế độ ${icon('arrow','sm')}</button></div><div class="mode-grid">${modeIds.map((id,i)=>modeCard(id,i===0)).join('')}</div>
 <div class="bottom-grid"><div class="panel"><div class="flex between"><h3 class="panel-title">Hoạt động gần đây</h3><button class="text-link" data-action="nav" data-path="records">Xem tất cả ${icon('arrow','sm')}</button></div>${recent||`<div class="empty">${icon('sparkles')}<p>Chưa có lượt thi nào. Thử Marathon 60s để bắt đầu!</p><button class="btn small primary" data-action="start" data-mode="marathon">Chơi ngay</button></div>`}</div>
 <div class="panel"><div class="flex between"><h3 class="panel-title">Bảng xếp hạng cá nhân</h3><span class="chip">Trên trình duyệt này</span></div>${bestByName.length?bestByName.map(([name,score],i)=>`<div class="ranking"><span class="rank-no">${String(i+1).padStart(2,'0')}</span><div class="avatar rank-avatar">${esc(name.slice(0,1).toLocaleUpperCase('vi'))}</div><span class="rank-name">${esc(name)}</span><span class="rank-xp num">${number(score)} đ</span></div>`).join(''):`<div class="empty">${icon('trophy')}<p>Hoàn thành lượt thi đầu tiên để xuất hiện trên bảng này.</p></div>`}</div></div>`;}
function playPage(){return `<div class="page-heading"><div><div class="eyebrow">YOUR NEXT CHALLENGE</div><h1>Đấu trường tri thức</h1><p>Không cần tài khoản, chọn một chế độ là có thể bắt đầu ngay.</p></div><span class="chip lime">7 chế độ cá nhân</span></div><div class="feature-row"><div><div class="eyebrow">CHẾ ĐỘ NỔI BẬT</div><h2>4 vòng thi · 1 đỉnh vinh quang</h2><p>Khởi động, Vượt chướng ngại vật, Tăng tốc và Về đích trong cùng một hành trình.</p></div><button class="btn primary" data-action="nav" data-path="mode/olympia">Vào đấu trường ${icon('arrow','sm')}</button><span class="feature-emblem">04</span></div><div class="section-head"><div><h2>Tất cả chế độ</h2><p>Mỗi chế độ mang đến một kiểu thử thách khác nhau.</p></div></div><div class="mode-grid">${Object.keys(MODE_INFO).map(id=>modeCard(id,id==='olympia')).join('')}</div><div class="notice mt-28">${icon('shield','sm')} Điểm số và lịch sử được lưu cục bộ trong trình duyệt của bạn. Chế độ thi nhiều thiết bị có tại mục <strong>Phòng thi online</strong> sau khi thiết lập Firebase.</div>`;}
function introPage(id){const m=MODE_INFO[id];if(!m)return playPage();const features={
 olympia:['Khởi động: 6 câu hỏi, 10 điểm/câu.','Vượt chướng ngại vật: 4 gợi ý và 1 từ khóa bí ẩn.','Tăng tốc: 4 câu, càng nhanh điểm càng cao.','Về đích: 3 câu, có ngôi sao hy vọng.'],
 marathon:['Tối đa 30 câu hỏi kiến thức tổng hợp.','Toàn bộ lượt chơi chỉ kéo dài 60 giây.','Trả lời nhanh bằng cách nhập đáp án và Enter.','Đúng được 10 điểm, có thể bỏ qua câu khó.'],
 hurdling:['4 câu đầu: 10 điểm, 10 giây mỗi câu.','3 câu tiếp: 20 điểm, 15 giây mỗi câu.','2 câu sau: 30 điểm, 20 giây mỗi câu.','Câu cuối: 40 điểm, 25 giây.'],
 math:['20 phép tính được tạo tự động.','90 giây cho toàn bộ lượt chơi.','Phép cộng, trừ, nhân, chia với kết quả nguyên.','Thưởng điểm chuỗi khi trả lời đúng liên tục.'],
 logic:['10 câu về quy luật, suy luận và giải mã.','Mỗi câu có 25 giây để lựa chọn.','15 điểm cho một câu đúng.','Hiển thị lời giải sau khi trả lời.'],
 vocab:['15 từ tiếng Anh được chọn ngẫu nhiên.','Nhập nghĩa tiếng Việt trong 20 giây/từ.','10 điểm cho mỗi câu trả lời đúng.','Có giải thích nghĩa tiếng Anh của mỗi từ.'],
 duel:['10 câu hỏi đối kháng, mỗi câu có 15 giây.','Đối thủ máy mô phỏng tự động ghi điểm theo xác suất.','Mỗi câu đúng được 10 điểm.','Đây là BOT luyện tập, không phải một người chơi thật hoặc mô hình AI.'],
 };
 return `<div class="game-layout"><button class="back-link" data-action="nav" data-path="play">${icon('chevron','sm')} Quay lại đấu trường</button><div class="panel" style="padding:clamp(24px,4vw,45px);background:radial-gradient(circle at 90% 20%,#254a3655,transparent 40%),#132129"><div class="flex" style="gap:14px"><span class="mode-icon" style="height:60px;width:60px;display:grid;place-items:center;background:#304c34;border-radius:18px;color:var(--lime)">${icon(m.icon,'xl')}</span><div><div class="eyebrow">SẴN SÀNG THỬ THÁCH?</div><h1 style="font-size:clamp(29px,3vw,43px);margin:9px 0 0">${m.title}</h1></div></div><p style="color:#adbfbb;margin:22px 0;max-width:550px">${m.subtitle} Hãy tập trung và chọn thời điểm để bứt phá.</p><div class="chips"><span class="chip lime">${icon('clock','sm')} ${m.time}</span><span class="chip">Chơi một mình</span><span class="chip">Tự động chấm điểm</span></div>${id==='marathon'?`<div class="field mt-20" style="max-width:300px"><label for="mode-topic">Chọn chủ đề Marathon</label><select class="select" id="mode-topic"><option value="all">Tổng hợp mọi môn học</option>${TOPICS.filter(t=>bank().some(q=>q.type==='text'&&q.topic===t&&!q.id.startsWith('v'))).map(t=>`<option value="${esc(t)}" ${t===marathonTopic?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`:''}<div class="divider"></div><h3 style="font-size:19px">Luật chơi</h3><div class="stack">${features[id].map((f,i)=>`<div class="flex" style="font-size:13px"><span style="color:var(--lime);font-weight:800;font-family:var(--display)">${String(i+1).padStart(2,'0')}</span><span>${f}</span></div>`).join('')}</div><div class="form-actions mt-28"><button class="btn large primary" data-action="start" data-mode="${id}">Bắt đầu thử thách ${icon('arrow')}</button><button class="btn ghost" data-action="nav" data-path="play">Chọn chế độ khác</button></div></div></div>`;}

const STAGES=[{key:'warmup',label:'Khởi động',desc:'Đánh thức vốn kiến thức của bạn với 6 câu hỏi ngắn.',count:6},{key:'obstacle',label:'Vượt chướng ngại vật',desc:'Lần theo 4 gợi ý và tìm từ khóa bí ẩn.',count:5},{key:'speed',label:'Tăng tốc',desc:'Mỗi giây đều có giá trị. Chốt đáp án thật nhanh.',count:4},{key:'finish',label:'Về đích',desc:'Lựa chọn ngôi sao hy vọng và khép lại cuộc chinh phục.',count:3}];
function makeMath(count=20){return Array.from({length:count},(_,i)=>{
 const op=['+','−','×','÷'][Math.floor(Math.random()*4)];let a,b,answer;
 if(op==='+'){a=Math.floor(Math.random()*80)+10;b=Math.floor(Math.random()*80)+10;answer=a+b;}
 if(op==='−'){a=Math.floor(Math.random()*90)+20;b=Math.floor(Math.random()*a);answer=a-b;}
 if(op==='×'){a=Math.floor(Math.random()*13)+3;b=Math.floor(Math.random()*11)+3;answer=a*b;}
 if(op==='÷'){answer=Math.floor(Math.random()*14)+2;b=Math.floor(Math.random()*11)+2;a=answer*b;}
 return {id:'calc'+i,type:'text',topic:'Toán học',q:`${a} ${op} ${b} = ?`,answer:String(answer),answers:[String(answer)],explanation:`${a} ${op} ${b} = ${answer}`};
 });}
function olympiaSet(){const dict=new Map(bank().map(q=>[q.id,q]));const picks=[['m01','c01','p01','h01','g02','l01'],[],['q01','q03','q05','q10'],['b05','p10','m10']];
 return [
 ...picks[0].map(id=>({...dict.get(id),stage:'warmup',points:10,seconds:15})),
 ...OBSTACLE.hints.map(q=>({...q,stage:'obstacle',points:10,seconds:20})),
 {id:'ob-final',type:'text',topic:'Từ khóa bí ẩn',q:'Từ khóa của chướng ngại vật là gì? (Gợi ý: quá trình tạo chất hữu cơ nhờ ánh sáng)',answer:OBSTACLE.keyword,answers:[OBSTACLE.keyword],explanation:OBSTACLE.explanation,stage:'obstacle',points:40,seconds:25,keyword:true},
 ...picks[2].map(id=>({...dict.get(id),stage:'speed',seconds:25,points:40})),
 ...picks[3].map((id,i)=>({...dict.get(id),stage:'finish',seconds:30,points:[10,20,30][i]}))];
}
function buildQuestions(type){const qs=bank();const shorts=qs.filter(q=>q.type==='text' && !q.id.startsWith('v'));
 if(type==='marathon')return shuffle(marathonTopic==='all'?shorts:shorts.filter(q=>q.topic===marathonTopic)).slice(0,30);
 if(type==='hurdling')return shuffle(shorts).slice(0,10);
 if(type==='logic')return shuffle([...LOGIC,...profile.custom.filter(q=>q.topic==='Tư duy logic')]).slice(0,10);
 if(type==='duel')return shuffle([...QUESTIONS.filter(q=>q.type==='choice'),...LOGIC,...profile.custom.filter(q=>q.type==='choice')]).slice(0,10);
 if(type==='vocab')return shuffle([...VOCAB,...profile.custom.filter(q=>q.topic==='Tiếng Anh'&&q.type==='text')]).slice(0,15);
 if(type==='math')return makeMath(20);
 if(type==='olympia')return olympiaSet();
 return [];
}
function qSeconds(g,q){if(g.mode==='marathon')return 60;if(g.mode==='math')return 90;if(g.mode==='hurdling')return [10,10,10,10,15,15,15,20,20,25][g.idx]||10;if(g.mode==='logic')return 25;if(g.mode==='vocab')return 20;if(g.mode==='duel')return 15;return q.seconds||15;}
function qPoints(g,q){if(g.mode==='hurdling')return [10,10,10,10,20,20,20,30,30,40][g.idx];if(g.mode==='logic')return 15;if(g.mode==='olympia')return q.points||10;return 10;}
function startGame(type){if(!MODE_INFO[type])return;
 clearInterval(quizInterval);const questions=buildQuestions(type);if(!questions.length){toast('Chưa có đủ câu hỏi cho chế độ này.',true);return;}
 game={mode:type,questions,idx:0,score:0,correct:0,wrong:0,combo:0,bestCombo:0,results:[],phase:type==='olympia'?'stage':'question',selected:'',botScore:0,star:false,starUsed:false,stage:0,startedAt:Date.now(),deadline:0,seconds:0,totalSeconds:type==='marathon'?60:type==='math'?90:0};
 navigate('game');render();if(game.phase==='question')armTimer(true);
}
function armTimer(initial=false){clearInterval(quizInterval);if(!game||game.phase!=='question')return;const q=game.questions[game.idx];
 if(!(initial&&game.totalSeconds))game.seconds=qSeconds(game,q);
 else game.seconds=game.totalSeconds;
 if(game.totalSeconds && game.mainDeadline)game.deadline=game.mainDeadline;
 else{game.deadline=Date.now()+game.seconds*1000;if(game.totalSeconds)game.mainDeadline=game.deadline;}
 refreshTimer();quizInterval=setInterval(refreshTimer,100);
}
function refreshTimer(){if(game?.phase!=='question')return;const rem=Math.max(0,(game.deadline-Date.now())/1000);const val=$('#time-value'),ring=$('#timer-ring');const integer=Math.ceil(rem);
 if(val)val.textContent=String(integer).padStart(2,'0');if(ring){ring.style.setProperty('--progress',(100*rem/(game.seconds||1))+'%');ring.classList.toggle('urgent',rem<=5);}
 if(rem<=0){clearInterval(quizInterval);if(game.totalSeconds)finishGame();else submitAnswer('',true);}
}
function currentQuestion(){return game?.questions[game.idx]||null;}
function stageFor(q){return STAGES.findIndex(s=>s.key===q.stage);}
function submitAnswer(forced=null,timeout=false,skip=false){if(!game||game.phase!=='question')return;
 const q=currentQuestion();const typed=forced!==null?forced:(q.type==='choice'?game.selected:$('#answer-input')?.value||'');
 if(!typed.trim() && !timeout && !skip){toast('Hãy nhập hoặc chọn một đáp án.',true);return;}
 const correct=!skip&&!timeout&&same(typed,q);const secondsUsed=Math.max(0,game.seconds-Math.max(0,(game.deadline-Date.now())/1000));let gain=0;
 if(correct){gain=qPoints(game,q);if(game.mode==='math')gain+=Math.min(10,game.combo*2);
 if(game.mode==='olympia'&&q.stage==='speed'){const remain=game.seconds-secondsUsed;gain=remain>=18?40:remain>=12?30:remain>=6?20:10;}
 if(game.mode==='olympia'&&q.stage==='finish'&&game.star)gain*=2;
 game.correct++;game.combo++;game.bestCombo=Math.max(game.combo,game.bestCombo);
 } else {game.wrong++;game.combo=0;if(game.mode==='olympia'&&q.stage==='finish'&&game.star)gain=-qPoints(game,q);}
 if(game.mode==='olympia'&&q.stage==='finish'&&game.star)game.starUsed=true;
 game.score+=gain;
 if(game.mode==='duel'){game.botLastGain=Math.random()<.64?10:0;game.botScore+=game.botLastGain;}
 game.results.push({q,answer:typed,correct,timeout,skip,gain});game.selected='';game.star=false;
 notifySound(correct);
 if(game.totalSeconds){game.idx++;if(game.idx>=game.questions.length){finishGame();return;}game.phase='question';render();refreshTimer();$('#answer-input')?.focus();return;}
 clearInterval(quizInterval);game.phase='feedback';game.lastGain=gain;render();
}
function goNext(){if(!game||game.phase!=='feedback')return;game.idx++;
 if(game.idx>=game.questions.length){finishGame();return;}
 if(game.mode==='olympia'){const nextStage=stageFor(game.questions[game.idx]);if(nextStage!==game.stage){game.stage=nextStage;game.phase='stage';render();return;}}
 game.phase='question';render();armTimer();
}
function nextStage(){if(!game||game.phase!=='stage')return;game.phase='question';render();armTimer();}
function finishGame(){if(!game||game.phase==='done')return;clearInterval(quizInterval);
 game.phase='done';const gain=Math.max(10,Math.round(Math.max(0,game.score)*.6)+game.correct*2),date=today();
 const last=profile.lastPlay;if(last!==date){const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const y=yesterday.toLocaleDateString('en-CA');profile.streak=last===y?(profile.streak||0)+1:1;profile.lastPlay=date;}
 profile.xp+=gain;game.xpGain=gain;profile.history.unshift({date:Date.now(),name:profile.name,mode:game.mode,score:game.score,xp:gain,correct:game.correct,total:game.results.length,time:Math.round((Date.now()-game.startedAt)/1000)});
 profile.history=profile.history.slice(0,150);persist();render();if(game.correct>0)celebrate();}
function questionGamePage(){const q=currentQuestion();const m=mode(game.mode),feedback=game.phase==='feedback',isOlympia=game.mode==='olympia';const point=qPoints(game,q);
 const options=q.type==='choice'?`<div class="option-grid">${q.options.map((op,i)=>`<button class="option ${game.selected===op?'selected':''} ${feedback?(same(op,q)?'correct':(game.results.at(-1)?.answer===op?'wrong':'')):''}" data-action="option" data-value="${esc(op)}" ${feedback?'disabled':''}><span class="option-key">${'ABCD'[i]}</span>${esc(op)}</button>`).join('')}</div>`:`<input class="answer-input" id="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Nhập đáp án của bạn..." aria-label="Đáp án" ${feedback?'disabled':''} ${feedback?`value="${esc(game.results.at(-1)?.answer||'')}"`:''}><div class="answer-tip">Nhấn <code>Enter ↵</code> để chốt · Không cần phân biệt dấu và chữ hoa/thường</div>`;
 const last=game.results.at(-1);const displayScore=`${game.score>=0?'+':''}${number(game.score)}`;
 const time=game.totalSeconds?game.totalSeconds:qSeconds(game,q);
 return `<div class="game-layout"><div class="game-topline"><button class="back-link" data-action="quit">${icon('chevron','sm')} Thoát lượt thi</button><span class="chip ${isOlympia?'gold':'lime'}">${isOlympia?STAGES[game.stage].label:m.time}</span></div><div class="game-heading"><div class="big-mode-icon">${icon(m.icon,'lg')}</div><div><h1>${m.title}</h1><p>${isOlympia?STAGES[game.stage].desc:m.subtitle}</p></div></div><div class="game-cols mt-28"><div><div class="question-card"><div class="q-head"><span class="q-topic">${icon('sparkles','sm')} ${esc(q.topic)}</span><span class="q-index">CÂU <strong>${String(game.idx+1).padStart(2,'0')}</strong> / ${String(game.questions.length).padStart(2,'0')}</span></div><h2 class="q-title">${esc(q.q)}</h2>${feedback?`<div class="feedback ${last.correct?'':'wrong'}"><div class="feedback-title">${icon(last.correct?'check':'x','sm')} ${last.correct?'Chính xác!':'Chưa chính xác'} · ${last.gain>0?'+':''}${last.gain} điểm</div><p class="feedback-answer">Đáp án: ${esc(q.answer)}</p><p>${esc(q.explanation||'Đối chiếu lại đáp án và thử sức với câu tiếp theo.')}</p></div>`:options}
 ${feedback&&game.mode==='duel'?`<div class="notice mt-12">Đối thủ máy: +${game.botLastGain} điểm vòng này · Tổng ${game.botScore} điểm.</div>`:''}
 ${!feedback&&isOlympia&&q.stage==='finish'?`<label class="star-pick"><input type="checkbox" id="star-checkbox" ${game.star?'checked':''} ${game.starUsed?'disabled':''}>${icon('star','sm')} Ngôi sao hy vọng: đúng x2, sai trừ ${point} điểm ${game.starUsed?'(đã sử dụng)':''}</label>`:''}
 ${!feedback&&isOlympia&&q.stage==='obstacle'?`<div class="stage-callout">${icon('help','sm')} ${q.keyword?'Gợi ý: xem lại 4 hàng ngang trước đó.':`Hàng ngang ${game.idx-5} / 4 · Đáp đúng để nhận thêm dữ kiện.`}</div>`:''}
 <div class="question-actions"><button class="btn ghost" data-action="${feedback?'nav':'skip'}" data-path="play">${feedback?'Chọn chế độ khác':'Bỏ qua câu này'}</button><button class="btn primary" data-action="${feedback?'next':'submit'}">${feedback?(game.idx===game.questions.length-1?'Xem kết quả':'Câu tiếp theo'):'Chốt đáp án'} ${icon('arrow','sm')}</button></div><div class="progress-track"><div class="progress-fill" style="width:${Math.round(100*(game.idx+(feedback?1:0))/game.questions.length)}%"></div></div></div></div>
 <aside class="game-side"><div class="timer-panel"><div class="timer-ring" id="timer-ring" style="--progress:100%"><div class="time-value num" id="time-value">${feedback?'—':String(time).padStart(2,'0')}</div><span class="time-label">GIÂY CÒN LẠI</span></div><div class="timer-caption">${feedback?'Đã chốt câu hỏi':'Thời gian để bứt phá'}</div></div><div class="side-score"><div class="side-top"><span>ĐIỂM HIỆN TẠI</span><span>${point} Đ/CÂU${game.mode==='math'?' + combo':''}</span></div><div class="score-number num">${displayScore}</div><div class="score-small">Điểm chinh phục</div>${game.mode==='duel'?`<div class="notice mt-12">${icon('users','sm')} Đối thủ máy: <strong>${game.botScore} điểm</strong></div>`:''}<div class="mini-stats"><div class="mini-stat"><strong>${game.correct}</strong><span>Đúng</span></div><div class="mini-stat"><strong>${game.bestCombo}</strong><span>Combo tốt nhất</span></div></div></div>${isOlympia?`<div class="round-path"><h3>Hành trình 4 vòng</h3>${STAGES.map((s,i)=>`<div class="round-step ${i===game.stage?'active':i<game.stage?'done':''}"><span class="round-dot">${i<game.stage?icon('check','sm'):i+1}</span><span>${s.label}</span>${i===game.stage?'<strong>ĐANG THI</strong>':''}</div>`).join('')}</div>`:''}</aside></div></div>`;
}
function stageGamePage(){const s=STAGES[game.stage];return `<div class="game-layout"><button class="back-link" data-action="quit">${icon('chevron','sm')} Thoát lượt thi</button><div class="stage-banner"><span class="eyebrow" style="justify-content:center">HÀNH TRÌNH CHINH PHỤC</span><div class="stage-number">0${game.stage+1}</div><h2>${s.label}</h2><p>${s.desc}</p><div class="stage-badges"><span class="chip lime">${s.count} câu hỏi</span><span class="chip gold">${number(game.score)} điểm hiện tại</span></div><button class="btn primary large" data-action="stage-next">${game.stage===0?'Bắt đầu vòng thi':'Tiến vào vòng tiếp theo'} ${icon('arrow')}</button></div><div class="round-path" style="max-width:740px;margin:15px auto"><div class="flex between">${STAGES.map((item,i)=>`<span class="chip ${i===game.stage?'lime':''}">${i+1}. ${item.label}</span>`).join('')}</div></div></div>`;}
function resultPage(){const m=mode(game.mode),total=game.results.length,pct=total?Math.round(game.correct/total*100):0;return `<div class="game-layout"><button class="back-link" data-action="nav" data-path="play">${icon('chevron','sm')} Quay về đấu trường</button><div class="result-card"><div class="result-symbol">${icon('trophy')}</div><div class="eyebrow" style="justify-content:center">HÀNH TRÌNH HOÀN THÀNH</div><h1>${game.mode==='duel'?(game.score>game.botScore?'Bạn đã chiến thắng!':game.score===game.botScore?'Trận đấu hòa!':'Đối thủ giành chiến thắng!'):(pct>=80?'Xuất sắc!':pct>=50?'Một bước tiến mới!':'Cứ tiếp tục tiến lên!')}</h1><p>${esc(m.title)} · Mọi câu trả lời đều mang đến điều để học.</p><div class="result-score num">${number(game.score)} <small>ĐIỂM</small></div><div class="chip lime" style="display:inline-flex">+${number(game.xpGain||0)} XP kinh nghiệm</div>${game.mode==='duel'?`<p class="mt-12">Bạn: <strong>${game.score}</strong> điểm · BOT: <strong>${game.botScore}</strong> điểm</p>`:''}<div class="result-stats"><div class="result-stat"><strong>${game.correct}</strong><span>Trả lời đúng</span></div><div class="result-stat"><strong>${pct}%</strong><span>Độ chính xác</span></div><div class="result-stat"><strong>${game.bestCombo}</strong><span>Combo cao nhất</span></div></div><div class="result-actions"><button class="btn primary" data-action="start" data-mode="${game.mode}">${icon('refresh','sm')} Chơi lại</button><button class="btn outline" data-action="nav" data-path="play">Chế độ khác</button><button class="btn outline" data-action="nav" data-path="records">Thành tích của tôi</button></div></div><div class="result-review"><div class="section-head"><h2>Đáp án & Giải thích</h2><span class="chip">${total} câu đã xử lý</span></div>${game.results.map((r,i)=>`<div class="review-row"><strong>${r.correct?'✓':'✕'} &nbsp; ${i+1}. ${esc(r.q.q)}</strong><p class="${r.correct?'is-correct':'is-wrong'}">Bạn trả lời: ${esc(r.answer||'(bỏ qua / hết giờ)')}</p><p>Đáp án: <strong style="display:inline">${esc(r.q.answer)}</strong> · ${esc(r.q.explanation||'')}</p></div>`).join('')}</div></div>`;}
function gamePage(){if(!game)return `<div class="empty">Chưa có lượt chơi. <button class="btn primary" data-action="nav" data-path="play">Vào đấu trường</button></div>`;return game.phase==='done'?resultPage():game.phase==='stage'?stageGamePage():questionGamePage();}

const PAGE_SIZE=18;
function matchesBank(q){const term=norm(filter.text);return(!term || norm(q.q+' '+q.topic+' '+q.answer).includes(term))&&(filter.topic==='all'||q.topic===filter.topic)&&(filter.type==='all'||q.type===filter.type);}
function libraryRows(){const all=bank().filter(matchesBank),pages=Math.max(1,Math.ceil(all.length/PAGE_SIZE)),page=Math.min(filter.page,pages-1);filter.page=page;return `<div class="flex between mt-20"><span class="count">Hiển thị ${all.length? page*PAGE_SIZE+1:0}–${Math.min(all.length,(page+1)*PAGE_SIZE)} trên ${number(all.length)} câu hỏi</span><span class="chip">${number(profile.custom.length)} câu bạn thêm</span></div><div class="bank-list mt-12">${all.slice(page*PAGE_SIZE,(page+1)*PAGE_SIZE).map(q=>`<article class="bank-row"><div class="bank-icon">${icon(q.type==='choice'?'target':'book','sm')}</div><div style="min-width:0;flex:1"><h3>${esc(q.q)}</h3><div class="bank-meta"><span class="chip lime">${esc(q.topic)}</span><span class="chip">${q.type==='choice'?'Trắc nghiệm':'Trả lời ngắn'}</span>${profile.custom.some(c=>c.id===q.id)?'<span class="chip gold">Do bạn tạo</span>':''}</div><details class="bank-details"><summary style="cursor:pointer;color:var(--lime);font-weight:800">Xem đáp án & giải thích</summary><p><strong>Đáp án:</strong> ${esc(q.answer)}</p><p>${esc(q.explanation||'Chưa có giải thích.')}</p></details></div>${profile.custom.some(c=>c.id===q.id)?`<div class="bank-actions"><button title="Sửa câu hỏi" data-action="edit-question" data-id="${esc(q.id)}">${icon('settings','sm')}</button><button title="Xóa câu hỏi" data-action="delete-question" data-id="${esc(q.id)}">${icon('trash','sm')}</button></div>`:''}</article>`).join('')||`<div class="empty">${icon('search')}<p>Không tìm thấy câu hỏi phù hợp. Thử thay đổi bộ lọc.</p></div>`}</div><div class="flex between mt-20"><button class="btn small ghost" data-action="bank-page" data-dir="-1" ${page<=0?'disabled':''}>Trang trước</button><span class="muted small">Trang ${page+1}/${pages}</span><button class="btn small ghost" data-action="bank-page" data-dir="1" ${page>=pages-1?'disabled':''}>Trang sau</button></div>`;}
function libraryPage(){return `<div class="page-heading"><div><div class="eyebrow">KNOWLEDGE IS POWER</div><h1>Kho câu hỏi</h1><p>Khám phá, tìm kiếm, tự tạo và nhập bộ câu hỏi của riêng bạn.</p></div><div class="library-actions"><button class="btn ghost small" data-action="export-bank">${icon('download','sm')} Xuất JSON</button><button class="btn ghost small" data-action="import-bank">${icon('upload','sm')} Nhập JSON</button><button class="btn primary small" data-action="add-question">${icon('plus','sm')} Thêm câu hỏi</button></div></div><div class="panel" style="padding:16px 19px"><div class="filter-bar" style="margin:0"><input class="input" id="bank-search" placeholder="Tìm theo câu hỏi, đáp án, chủ đề..." value="${esc(filter.text)}" aria-label="Tìm kiếm câu hỏi"><select class="select" id="bank-topic" aria-label="Chọn chủ đề"><option value="all">Tất cả môn học</option>${TOPICS.map(t=>`<option ${filter.topic===t?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select><select class="select" id="bank-type" aria-label="Kiểu câu hỏi"><option value="all">Tất cả hình thức</option><option value="text" ${filter.type==='text'?'selected':''}>Trả lời ngắn</option><option value="choice" ${filter.type==='choice'?'selected':''}>Trắc nghiệm</option></select></div></div><div id="bank-results">${libraryRows()}</div><div class="notice mt-20">${icon('help','sm')} Câu hỏi mặc định là dữ liệu luyện tập tự biên soạn. Bộ câu hỏi nhập vào chỉ lưu trên thiết bị hiện tại; hãy dùng <strong>Xuất JSON</strong> để sao lưu.</div>`;}
function exportJSON(filename,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function questionModal(id=''){const q=profile.custom.find(x=>x.id===id);currentModal={type:'question',id};const options=q?.options?.join('\n')||'';document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="dialog-overlay"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${q?'Chỉnh sửa câu hỏi':'Tạo câu hỏi mới'}</h2><button class="icon-btn" data-action="close-modal" aria-label="Đóng">${icon('x')}</button></div><form id="question-form" class="stack"><div class="form-grid"><div class="field"><label for="q-topic">Môn học</label><select id="q-topic" class="select" name="topic">${TOPICS.map(t=>`<option ${q?.topic===t?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><div class="field"><label for="q-type">Hình thức</label><select id="q-type" class="select" name="type"><option value="text" ${q?.type!=='choice'?'selected':''}>Trả lời ngắn</option><option value="choice" ${q?.type==='choice'?'selected':''}>Trắc nghiệm</option></select></div></div><div class="field"><label for="q-content">Nội dung câu hỏi</label><textarea id="q-content" name="q" class="textarea" required maxlength="400" placeholder="Ví dụ: Đơn vị đo tần số là gì?">${esc(q?.q||'')}</textarea></div><div class="field"><label for="q-answer">Đáp án đúng</label><input class="input" id="q-answer" name="answer" value="${esc(q?.answer||'')}" required maxlength="180" placeholder="Đáp án chính xác"></div><div class="field"><label for="q-options">Lựa chọn A, B, C, D (mỗi lựa chọn một dòng, chỉ dùng cho trắc nghiệm)</label><textarea id="q-options" name="options" class="textarea" placeholder="Đáp án A&#10;Đáp án B&#10;Đáp án C&#10;Đáp án D">${esc(options)}</textarea></div><div class="field"><label for="q-explanation">Giải thích (khuyến khích)</label><textarea id="q-explanation" name="explanation" class="textarea" placeholder="Giải thích vì sao đáp án đúng...">${esc(q?.explanation||'')}</textarea></div><div class="form-actions"><button type="submit" class="btn primary">${q?'Lưu thay đổi':'Thêm vào ngân hàng'} ${icon('check','sm')}</button><button type="button" class="btn ghost" data-action="close-modal">Hủy</button></div></form></div></div>`);$('#q-content')?.focus();}
function closeModal(){$('#dialog-overlay')?.remove();currentModal='';}
function saveQuestion(form){const fd=new FormData(form),type=fd.get('type'),q=String(fd.get('q')||'').trim(),answer=String(fd.get('answer')||'').trim(),opts=String(fd.get('options')||'').split('\n').map(s=>s.trim()).filter(Boolean);
 if(!q||!answer){toast('Hãy nhập câu hỏi và đáp án.',true);return;}
 if(type==='choice'&&(opts.length!==4||!opts.includes(answer))){toast('Trắc nghiệm phải có đúng 4 lựa chọn; đáp án phải trùng một lựa chọn.',true);return;}
 const id=currentModal?.id||'custom-'+Date.now()+'-'+Math.random().toString(36).slice(2,5);const question={id,q,topic:String(fd.get('topic')),type,answer,answers:[answer],options:type==='choice'?opts:undefined,explanation:String(fd.get('explanation')||'').slice(0,500),level:1};
 const idx=profile.custom.findIndex(x=>x.id===id);if(idx>=0)profile.custom[idx]=question;else profile.custom.unshift(question);persist();closeModal();render();toast('Đã lưu câu hỏi vào ngân hàng.');}
async function importBank(file){if(!file)return;try{const raw=JSON.parse(await file.text()),list=Array.isArray(raw)?raw:raw.questions;if(!Array.isArray(list))throw new Error('File phải chứa một mảng câu hỏi hoặc thuộc tính questions.');let added=0;
 for(const item of list.slice(0,1000)){if(!item||typeof item.q!=='string'||typeof item.answer!=='string'||!item.q.trim()||!item.answer.trim())continue;
 const type=item.type==='choice'?'choice':'text';const opts=type==='choice'&&Array.isArray(item.options)?item.options.map(String).slice(0,4):[];if(type==='choice'&&(opts.length!==4||!opts.includes(item.answer)))continue;
 const fresh={id:'import-'+Date.now()+'-'+Math.random().toString(36).slice(2,10),topic:TOPICS.includes(item.topic)?item.topic:'Tổng hợp',q:item.q.slice(0,400),answer:item.answer.slice(0,180),answers:[item.answer.slice(0,180),...(Array.isArray(item.answers)?item.answers.filter(x=>typeof x==='string').slice(0,4):[])],type,options:type==='choice'?opts:undefined,explanation:String(item.explanation||'').slice(0,500),level:1};profile.custom.push(fresh);added++;}
 persist();render();toast(`Đã nhập ${added} câu hỏi hợp lệ.`);}catch(err){toast('Lỗi nhập JSON: '+err.message,true);}finally{$('#jsonImport').value='';}}

function recordsPage(){const games=profile.history,lv=levelFor(profile.xp),correct=games.reduce((s,h)=>s+h.correct,0),total=games.reduce((s,h)=>s+h.total,0),best=games.reduce((m,h)=>Math.max(h.score,m),0),next=levelEnd(lv),start=levelStart(lv),pct=Math.min(100,Math.round((profile.xp-start)/(next-start)*100));
 const achieves=[['Bước chân đầu tiên','Hoàn thành lượt thi đầu tiên',games.length>=1,'flag'],['Bứt phá 100','Đạt ít nhất 100 điểm trong một lượt',best>=100,'zap'],['Người kiên trì','Hoàn thành 10 lượt chơi',games.length>=10,'trophy'],['Luyện tập đều','Chuỗi ít nhất 3 ngày',profile.streak>=3,'clock'],['Bậc thầy phản xạ','Tích lũy 2.000 XP',profile.xp>=2000,'bolt'],['Chạm đỉnh Olympia','Hoàn thành 1 lượt 4 vòng Olympia',games.some(g=>g.mode==='olympia'),'mountain']];
 return `<div class="page-heading"><div><div class="eyebrow">PROGRESS TRACKER</div><h1>Hành trình của bạn</h1><p>Những con số đánh dấu từng bước tiến trong quá trình luyện tập.</p></div><button class="btn ghost small" data-action="export-history">${icon('download','sm')} Sao lưu kết quả</button></div><div class="metric-grid">${[['Lượt hoàn thành',games.length,'trophy'],['Điểm cao nhất',best,'star'],['Độ chính xác',total?Math.round(correct/total*100)+'%':'0%','target']].map(([label,val,ic])=>`<div class="metric">${icon(ic)}<strong>${typeof val==='number'?number(val):val}</strong><span>${label}</span></div>`).join('')}</div><div class="panel mt-20"><div class="flex between"><h2 class="panel-title">Cấp độ chinh phục</h2><span class="chip lime">LEVEL ${lv}</span></div><div class="flex between small"><span class="muted">${number(profile.xp)} XP hiện có</span><strong>${number(next)} XP để đạt cấp ${lv+1}</strong></div><div class="level-track mt-12"><div style="width:${pct}%"></div></div></div><div class="section-head"><h2>Huy hiệu thành tích</h2><span class="chip">${achieves.filter(a=>a[2]).length}/${achieves.length} đã mở</span></div><div class="achievement-grid">${achieves.map(([name,desc,got,ic])=>`<div class="achievement ${got?'':'locked'}">${icon(ic,'lg')}<strong>${name}</strong><p>${desc}</p></div>`).join('')}</div><div class="section-head"><h2>Lịch sử luyện tập</h2><span class="muted small">Được lưu trên thiết bị này</span></div><div class="panel" style="overflow:auto">${games.length?`<table class="history-table"><thead><tr><th>Ngày</th><th>Chế độ</th><th>Người chơi</th><th>Đúng</th><th>Điểm</th><th>XP</th></tr></thead><tbody>${games.map(h=>`<tr><td class="nowrap">${dateLabel(h.date)}</td><td>${esc(mode(h.mode).title)}</td><td>${esc(h.name)}</td><td>${h.correct}/${h.total}</td><td><strong>${number(h.score)}</strong></td><td class="gain">+${number(h.xp)}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${icon('chart')}<p>Tham gia một thử thách để theo dõi tiến độ của bạn.</p></div>`}</div>`;}

function settingsPage(){return `<div class="page-heading"><div><div class="eyebrow">PERSONALIZE YOUR JOURNEY</div><h1>Cài đặt</h1><p>Cá nhân hóa trải nghiệm và quản lý dữ liệu được lưu trong trình duyệt.</p></div></div><div class="settings-grid"><div class="panel"><h2 class="panel-title">Hồ sơ người chơi</h2><form id="profile-form"><div class="field"><label for="profile-name">Tên hiển thị</label><input class="input" id="profile-name" name="name" maxlength="32" required value="${esc(profile.name)}" placeholder="Tên của bạn"></div><div class="form-actions"><button class="btn primary" type="submit">${icon('check','sm')} Lưu hồ sơ</button></div></form><div class="divider"></div><h2 class="panel-title">Tùy chọn trải nghiệm</h2><div class="setting-row"><div><strong>Âm thanh hiệu ứng</strong><p>Phát âm khi chốt đáp án đúng hoặc sai.</p></div><input class="toggle" type="checkbox" id="setting-sound" ${profile.settings.sound?'checked':''} aria-label="Âm thanh hiệu ứng"></div><div class="setting-row"><div><strong>Giảm hiệu ứng chuyển động</strong><p>Tắt confetti và các chuyển cảnh không cần thiết.</p></div><input class="toggle" type="checkbox" id="setting-motion" ${profile.settings.reduceMotion?'checked':''} aria-label="Giảm hiệu ứng"></div></div><div class="panel"><h2 class="panel-title">Dữ liệu và quyền riêng tư</h2><p class="muted small">Không có tài khoản bắt buộc. Thông tin cá nhân, câu hỏi tự thêm và lịch sử được lưu trong localStorage của trình duyệt, không được gửi lên máy chủ của dự án khi chơi offline.</p><div class="stack mt-20"><button class="btn ghost" data-action="export-all">${icon('download','sm')} Sao lưu toàn bộ dữ liệu (JSON)</button><button class="btn ghost" data-action="import-all">${icon('upload','sm')} Khôi phục từ bản sao lưu</button><button class="btn danger" data-action="reset-data">${icon('trash','sm')} Xóa toàn bộ dữ liệu cục bộ</button></div><div class="notice warn mt-20">${icon('help','sm')} Xóa dữ liệu sẽ không thể hoàn tác nếu bạn chưa sao lưu trước đó.</div></div></div><div class="panel mt-20"><h2 class="panel-title">Thông tin dự án</h2><p class="muted small mb-0">Đỉnh Tri Thức là dự án giao diện và trò chơi giáo dục độc lập, lấy cảm hứng từ cấu trúc các sân chơi kiến thức. Dự án không thuộc VTV, Đường lên đỉnh Olympia hay Ao Làng. Các câu hỏi được soạn riêng để luyện tập.</p></div>`;}

function defaultClassroom(){return {players:['Thí sinh 1','Thí sinh 2','Thí sinh 3','Thí sinh 4'].map((name,i)=>({name,score:0})),selected:0,idx:0,round:0,revealed:false,seconds:20,running:false,deadline:0};}
function classQuestions(){const ids=[['q01','c01','p01','h01','g02','l01','m01','t05'],['b03','c04','g05','b06','c06','p09','x03','h02'],['q10','q03','q15','q12','q04','q17','r01','r05'],['p10','m10','b05','q14','q16','h05','c11','g09']];const all=new Map(bank().map(q=>[q.id,q]));return ids[profile.classroom?.round||0].map(id=>all.get(id)).filter(Boolean);}
function persistClass(){persist();}
function classTimeTick(){const c=profile.classroom;if(!c||!c.running)return;c.seconds=Math.max(0,(c.deadline-Date.now())/1000);const el=$('#class-time');if(el){el.textContent=Math.ceil(c.seconds);el.classList.toggle('urgent',c.seconds<=5);}if(c.seconds<=0){clearInterval(classInterval);c.running=false;c.seconds=0;persistClass();toast('Hết giờ trả lời!');}}
function classroomPage(){const c=profile.classroom;
 if(!c)return `<div class="page-heading"><div><div class="eyebrow">LIVE CLASSROOM</div><h1>Phòng thi lớp học</h1><p>MC điều khiển câu hỏi, đồng hồ và điểm số cho tối đa 4 thí sinh.</p></div></div><div class="classroom-grid"><div class="panel"><h2 class="panel-title">Thiết lập trận đấu</h2><form id="class-setup" class="class-setup"><p class="muted small">Nhập tên 4 người chơi (có thể là tên 4 đội). Đây là chế độ thi trên một thiết bị có máy chiếu, không yêu cầu internet.</p>${[0,1,2,3].map(i=>`<div class="field"><label for="player-${i}">Thí sinh ${i+1}</label><input class="input" id="player-${i}" name="player-${i}" maxlength="32" placeholder="Tên thí sinh ${i+1}" value="Thí sinh ${i+1}"></div>`).join('')}<button class="btn primary" type="submit">Tạo phòng thi ${icon('arrow','sm')}</button></form></div><div class="panel"><h2 class="panel-title">Chức năng dành cho MC</h2><div class="stack">${['Điều khiển đồng hồ câu hỏi theo vòng thi','Ẩn/hiện đáp án để thí sinh trả lời','Chọn người chơi và cộng/trừ điểm trực tiếp','Bảng điểm liên tục được lưu tại thiết bị','Toàn màn hình để chiếu lên lớp'].map(text=>`<div class="flex" style="font-size:12px">${icon('check','sm')} ${text}</div>`).join('')}</div><div class="notice mt-20">${icon('help','sm')} Bạn có thể chuyển giữa bốn vòng thi và tự chấm điểm. Luật chấm điểm trong phòng lớp học do MC điều khiển.</div></div></div>`;
 const qs=classQuestions(),q=qs[c.idx%qs.length]||QUESTIONS[0];const max=c.round===3?30:c.round===2?25:20;return `<div class="page-heading"><div><div class="eyebrow">HOST CONTROL PANEL</div><h1>Đấu trường lớp học</h1><p>Chọn thí sinh · Bắt đầu đếm giờ · Chốt điểm</p></div><div class="library-actions"><button class="btn ghost small" data-action="fullscreen">${icon('target','sm')} Toàn màn hình</button><button class="btn danger small" data-action="class-reset">Kết thúc trận</button></div></div><div class="classroom-grid"><div><div class="panel class-question"><div class="flex between"><span class="chip lime">${esc(STAGES[c.round].label)}</span><span class="count">Câu ${c.idx+1} / ${qs.length}</span></div><h2>${esc(q.q)}</h2>${q.options?`<div class="option-grid" style="margin:15px 0">${q.options.map((v,i)=>`<div class="option ${c.revealed&&same(v,q)?'correct':''}"><span class="option-key">${'ABCD'[i]}</span>${esc(v)}</div>`).join('')}</div>`:''}${c.revealed?`<div class="reveal-box"><div class="micro muted">ĐÁP ÁN ĐÚNG</div><strong>${esc(q.answer)}</strong><p>${esc(q.explanation)}</p></div>`:''}</div><div class="panel mt-12"><div class="flex between" style="flex-wrap:wrap"><h3 class="panel-title" style="margin:0">Điều khiển MC</h3><select class="select" id="class-round" style="width:205px">${STAGES.map((s,i)=>`<option value="${i}" ${i===c.round?'selected':''}>Vòng ${i+1}: ${s.label}</option>`).join('')}</select></div><div class="host-controls mt-20"><button class="btn ghost" data-action="class-clock">${icon('clock','sm')} ${c.running?'Tạm dừng':'Bắt đầu giờ'}</button><button class="btn ghost" data-action="class-reveal">${icon('book','sm')} ${c.revealed?'Ẩn đáp án':'Hiện đáp án'}</button><button class="btn primary" data-action="class-next">Câu tiếp theo ${icon('arrow','sm')}</button></div><div class="muted small mt-12">Thao tác cộng/trừ điểm ở bảng thí sinh bên cạnh. Mỗi nút tương ứng 10 điểm.</div></div></div><aside class="game-side"><div class="panel"><div class="micro muted text-center">THỜI GIAN CÒN LẠI</div><div class="class-timer num" id="class-time">${Math.ceil(c.seconds)}</div><button class="btn outline w-full small" data-action="class-clock-reset">Đặt lại ${max} giây</button></div><div class="panel"><h3 class="panel-title">Bảng điểm trực tiếp</h3><div class="board-players">${c.players.map((p,i)=>`<div class="board-player ${c.selected===i?'active':''}" data-action="class-select" data-index="${i}"><div class="avatar">${esc(p.name.slice(0,1))}</div><span class="player-name">${esc(p.name)}</span><span class="player-score num">${number(p.score)}</span></div>`).join('')}</div><div class="form-actions"><button class="btn small primary" data-action="class-adjust" data-delta="10">${icon('plus','sm')} +10</button><button class="btn small ghost" data-action="class-adjust" data-delta="-10">−10</button></div><p class="muted small mt-12">Đang chọn: <strong style="color:var(--lime)">${esc(c.players[c.selected].name)}</strong></p></div></aside></div><div class="section-head"><h2>Điểm số hiện tại</h2></div><div class="score-podium">${[...c.players].sort((a,b)=>b.score-a.score).map((p,i)=>`<div class="podium-card"><span>VỊ TRÍ ${i+1}</span><strong>${number(p.score)}</strong><span>${esc(p.name)}</span></div>`).join('')}</div>`;}

const onlineQuestionPool=[...QUESTIONS.filter(q=>q.type==='choice'),...LOGIC,...QUESTIONS.filter(q=>q.type==='text')];
function onlineQuestion(room){return onlineQuestionPool[(Number(room.questionIdx||0)*7+3)%onlineQuestionPool.length];}
function liveQuestionById(id){return onlineQuestionPool.find(q=>q.id===id)||bank().find(q=>q.id===id);}
function onlinePage(){if(!isOnlineConfigured)return `<div class="page-heading"><div><div class="eyebrow">PLAY TOGETHER · LIVE</div><h1>Phòng thi trực tuyến</h1><p>Thi đấu nhiều thiết bị qua mã phòng và chuông giành quyền trả lời.</p></div><span class="chip gold">Cần cấu hình</span></div><div class="online-info"><div class="flex" style="color:var(--blue)">${icon('wifi')} PHÒNG THI NHIỀU THIẾT BỊ</div><h2 class="mt-20">Mở khóa phòng thi bằng Firebase</h2><p>Source đã có sẵn chức năng tạo phòng 6 ký tự, tham gia từ điện thoại khác, chuông ưu tiên người bấm trước, bảng điểm đồng bộ và giao diện MC điều khiển câu hỏi. Để sử dụng, bạn chỉ cần kết nối Firebase Realtime Database và bật xác thực ẩn danh.</p><div class="notice mt-20">${icon('help','sm')} Mở file <strong>FIREBASE_SETUP.md</strong> trong source để xem hướng dẫn từng bước. Sau đó điền cấu hình vào <strong>src/firebase-config.js</strong> và cập nhật lại GitHub Pages.</div><div class="form-actions"><button class="btn primary" data-action="nav" data-path="classroom">Thi lớp học không cần Firebase ${icon('arrow','sm')}</button><button class="btn outline" data-action="nav" data-path="play">Chơi cá nhân</button></div></div>`;
 if(!roomCode)return `<div class="page-heading"><div><div class="eyebrow">REALTIME ARENA</div><h1>Phòng thi trực tuyến</h1><p>Trận đấu đồng bộ nhiều thiết bị thông qua Firebase.</p></div></div><div class="settings-grid"><div class="panel"><h2 class="panel-title">Tạo phòng thi mới</h2><p class="muted small">Bạn sẽ là MC điều khiển câu hỏi, lật đáp án và phân xử điểm.</p><form id="create-room-form" class="stack"><div class="field"><label>Tên hiển thị của MC</label><input name="name" class="input" maxlength="32" value="${esc(profile.name)}" required></div><button type="submit" class="btn primary" ${onlineLoading?'disabled':''}>${onlineLoading?'Đang kết nối...':'Tạo phòng'} ${icon('arrow','sm')}</button></form></div><div class="panel"><h2 class="panel-title">Tham gia phòng có sẵn</h2><p class="muted small">Nhập mã 6 ký tự do MC cung cấp để tham gia trên thiết bị của bạn.</p><form id="join-room-form" class="stack"><div class="field"><label>Mã phòng</label><input name="code" class="input" maxlength="6" style="text-transform:uppercase;letter-spacing:.15em;font-family:var(--display)" required placeholder="ABC123"></div><div class="field"><label>Tên người chơi</label><input name="name" class="input" maxlength="32" value="${esc(profile.name)}" required></div><button type="submit" class="btn ghost" ${onlineLoading?'disabled':''}>Vào phòng ${icon('arrow','sm')}</button></form></div></div>${roomError?`<div class="notice warn mt-20">${esc(roomError)}</div>`:''}`;
 if(!roomState)return `<div class="online-info"><p>Đang tải trạng thái phòng ${esc(roomCode)}...</p><button class="btn ghost" data-action="room-exit">Thoát phòng</button></div>`;
 const r=roomState,players=Object.values(r.players||{}).sort((a,b)=>(b.score||0)-(a.score||0)),isHost=r.hostUid===window.__onlineUID,hasBuzz=Boolean(r.buzz),myBuzz=r.buzz?.uid===window.__onlineUID,q=r.question?liveQuestionById(r.question.id):null;
 return `<div class="page-heading"><div><div class="eyebrow">MULTIPLAYER · CONNECTED</div><h1>${isHost?'Phòng điều khiển MC':'Sân thi của bạn'}</h1><p>Đồng bộ theo thời gian thực · ${players.length} người trong phòng</p></div><button class="btn ghost small" data-action="room-exit">Rời phòng ${icon('x','sm')}</button></div><div class="online-info"><div class="flex between"><span class="room-status"><span class="live-dot"></span> PHÒNG ĐANG HOẠT ĐỘNG</span><span class="chip">${isHost?'BẠN LÀ MC':'THÍ SINH'}</span></div><div class="room-code">${esc(roomCode)}</div><p>Chia sẻ mã này cho bạn bè để cùng vào phòng. Mỗi người mở website trên thiết bị của mình.</p><button class="btn small ghost" data-action="copy-room">${icon('download','sm')} Sao chép mã phòng</button></div><div class="classroom-grid mt-20"><div class="panel"><div class="flex between"><span class="chip lime">${r.status==='lobby'?'Sảnh chờ':r.status==='question'?'Câu hỏi đang mở':'Đã công bố đáp án'}</span><span class="count">${r.questionIdx||0} câu đã mở</span></div>${!q?`<div style="padding:42px 10px;text-align:center">${icon('users','xl')}<h2 class="mt-20">Sẵn sàng vào trận?</h2><p class="muted small">${isHost?'Bấm nút bên dưới để ra câu hỏi đầu tiên.':'MC sẽ bắt đầu vòng thi khi mọi người đã có mặt.'}</p></div>`:`<div class="online-question">${esc(q.q)}</div>${q.options?`<div class="option-grid">${q.options.map((a,i)=>`<div class="option ${r.status==='reveal'&&same(a,q)?'correct':''}"><span class="option-key">${'ABCD'[i]}</span>${esc(a)}</div>`).join('')}</div>`:''}${r.status==='reveal'?`<div class="reveal-box"><div class="small muted">ĐÁP ÁN</div><strong>${esc(q.answer)}</strong><p>${esc(q.explanation)}</p></div>`:''}`}
 ${r.status==='question'?(isHost?`<div class="notice mt-20">${hasBuzz?`Người bấm chuông đầu tiên: <strong>${esc(r.buzz.name)}</strong>. MC nghe đáp án và chấm điểm.`:'Đang chờ thí sinh bấm chuông giành quyền trả lời.'}</div>`:`<button class="buzz-btn" data-action="room-buzz" ${hasBuzz?'disabled':''}>${hasBuzz?(myBuzz?'ĐÃ BẤM':'ĐÃ KHÓA'):'BẤM\nCHUÔNG!'}</button>`):''}
 ${isHost?`<div class="host-controls mt-20">${r.status==='question'?`<button class="btn primary" data-action="room-mark" data-correct="1" ${!hasBuzz?'disabled':''}>${icon('check','sm')} Đúng +10</button><button class="btn danger" data-action="room-mark" data-correct="0" ${!hasBuzz?'disabled':''}>${icon('x','sm')} Sai / 0đ</button><button class="btn ghost" data-action="room-reveal">Công bố đáp án</button>`:`<button class="btn primary" data-action="room-next">${r.status==='lobby'?'Bắt đầu câu đầu tiên':'Câu hỏi tiếp theo'} ${icon('arrow','sm')}</button>`}</div>`:''}</div><aside class="panel"><h3 class="panel-title">Bảng xếp hạng phòng</h3>${players.map((p,i)=>`<div class="room-row"><strong>${i+1}. ${esc(p.name)} ${p.uid===r.hostUid?'<small class="muted">(MC)</small>':''}</strong><span>${number(p.score)} đ</span></div>`).join('')||'<p class="muted">Chưa có người chơi.</p>'}<div class="notice mt-20">${icon('shield','sm')} MC điều khiển kết quả. Đây là mô hình giao lưu, không có chống gian lận cấp máy chủ.</div></aside></div>`;}
async function watchOnline(code){roomUnsub?.();roomUnsub=null;roomCode=code;roomState=null;roomError='';navigate('online');render();try{const info=await identity();window.__onlineUID=info.uid;roomUnsub=await subscribe(code,(data)=>{roomState=data;if(!data){roomError='Phòng đã đóng.';roomCode='';}if(route()==='online')render();},err=>{roomError=err.message;toast(roomError,true);});}catch(err){roomError=err.message;roomCode='';render();toast(err.message,true);}}
function leaveRoom(){roomUnsub?.();roomUnsub=null;roomCode='';roomState=null;roomError='';render();}
function findNewRoomQuestion(){const n=(roomState?.questionIdx||0)+1;return onlineQuestionPool[(n*7+3)%onlineQuestionPool.length];}

function render(){let path=route();if(!path)path='home';let content;
 if(path==='home')content=homePage();else if(path==='play')content=playPage();else if(path.startsWith('mode/'))content=introPage(path.split('/')[1]);else if(path==='game')content=gamePage();else if(path==='library')content=libraryPage();else if(path==='records')content=recordsPage();else if(path==='settings')content=settingsPage();else if(path==='classroom')content=classroomPage();else if(path==='online')content=onlinePage();else content=homePage();shell(content);
 if(path==='classroom'&&profile.classroom?.running){clearInterval(classInterval);classInterval=setInterval(classTimeTick,150);classTimeTick();}
 if(path==='game'&&game?.phase==='question'&&game.deadline)refreshTimer();
 document.body.classList.toggle('reduce-motion',profile.settings.reduceMotion);
}

// Mọi nút bấm đều dùng event delegation, tránh mất tương tác khi thay màn hình.
document.addEventListener('click', async event => {
 const node=event.target.closest('[data-action]');if(!node||node.disabled)return;
 const action=node.dataset.action;
 try{
  if(action==='nav'){navigate(node.dataset.path);return;}
  if(action==='menu'){mobileOpen=!mobileOpen;render();return;}
  if(action==='close-menu'){mobileOpen=false;render();return;}
  if(action==='search'){filter.text='';navigate('library');setTimeout(()=>$('#bank-search')?.focus(),25);return;}
  if(action==='sound'){profile.settings.sound=!profile.settings.sound;persist();render();toast(profile.settings.sound?'Đã bật âm thanh.':'Đã tắt âm thanh.');return;}
  if(action==='fullscreen'){if(!document.fullscreenElement){await document.documentElement.requestFullscreen?.();}else await document.exitFullscreen?.();return;}
  if(action==='start'){startGame(node.dataset.mode);return;}
  if(action==='quit'){if(window.confirm('Thoát lượt này? Điểm và tiến độ hiện tại sẽ không được lưu.')){clearInterval(quizInterval);game=null;navigate('play');}return;}
  if(action==='option'){if(game?.phase==='question'){game.selected=node.dataset.value;document.querySelectorAll('[data-action="option"]').forEach(b=>b.classList.toggle('selected',b===node));}return;}
  if(action==='submit'){submitAnswer();return;}
  if(action==='skip'){submitAnswer('',false,true);return;}
  if(action==='next'){goNext();return;}
  if(action==='stage-next'){nextStage();return;}
  if(action==='add-question'){questionModal();return;}
  if(action==='edit-question'){questionModal(node.dataset.id);return;}
  if(action==='close-modal'){closeModal();return;}
  if(action==='delete-question'){const q=profile.custom.find(c=>c.id===node.dataset.id);if(q&&window.confirm(`Xóa câu hỏi "${q.q.slice(0,90)}"?`)){profile.custom=profile.custom.filter(c=>c.id!==q.id);persist();render();toast('Đã xóa câu hỏi.');}return;}
  if(action==='bank-page'){filter.page=Math.max(0,filter.page+Number(node.dataset.dir));$('#bank-results').innerHTML=libraryRows();$('#bank-results').scrollIntoView({block:'start',behavior:'smooth'});return;}
  if(action==='export-bank'){exportJSON('dinh-tri-thuc-ngan-hang-cau-hoi.json',{version:1,questions:profile.custom,example:QUESTIONS[0]});toast('Đã xuất bộ câu hỏi cá nhân.');return;}
  if(action==='import-bank'){window.__importKind='bank';$('#jsonImport').click();return;}
  if(action==='export-history'){exportJSON('dinh-tri-thuc-thanh-tich.json',{name:profile.name,xp:profile.xp,streak:profile.streak,history:profile.history});return;}
  if(action==='export-all'){exportJSON('dinh-tri-thuc-sao-luu.json',{...profile,backupVersion:1});return;}
  if(action==='import-all'){window.__importKind='all';$('#jsonImport').click();return;}
  if(action==='reset-data'){if(window.confirm('Xóa VĨNH VIỄN hồ sơ, lịch sử, câu hỏi riêng và phòng thi lớp học trên trình duyệt này?')){profile=freshProfile();persist();game=null;render();toast('Đã đặt lại dữ liệu cục bộ.');}return;}
  if(action==='class-select'){const c=profile.classroom;if(!c)return;c.selected=Number(node.dataset.index);persistClass();render();return;}
  if(action==='class-adjust'){const c=profile.classroom;if(!c)return;c.players[c.selected].score+=Number(node.dataset.delta);persistClass();render();return;}
  if(action==='class-reveal'){const c=profile.classroom;if(!c)return;c.revealed=!c.revealed;persistClass();render();return;}
  if(action==='class-next'){const c=profile.classroom;if(!c)return;c.idx=(c.idx+1)%classQuestions().length;c.revealed=false;c.running=false;c.seconds=c.round===3?30:c.round===2?25:20;clearInterval(classInterval);persistClass();render();return;}
  if(action==='class-clock'){const c=profile.classroom;if(!c)return;if(c.running){c.seconds=Math.max(0,(c.deadline-Date.now())/1000);c.running=false;clearInterval(classInterval);}else{if(c.seconds<=0)c.seconds=c.round===3?30:c.round===2?25:20;c.deadline=Date.now()+c.seconds*1000;c.running=true;clearInterval(classInterval);classInterval=setInterval(classTimeTick,150);}persistClass();render();return;}
  if(action==='class-clock-reset'){const c=profile.classroom;if(!c)return;c.running=false;c.seconds=c.round===3?30:c.round===2?25:20;clearInterval(classInterval);persistClass();render();return;}
  if(action==='class-reset'){if(window.confirm('Kết thúc và xóa bảng điểm trận thi lớp học hiện tại?')){clearInterval(classInterval);profile.classroom=null;persistClass();render();}return;}
  if(action==='room-exit'){leaveRoom();return;}
  if(action==='copy-room'){await navigator.clipboard.writeText(roomCode);toast('Đã sao chép mã phòng.');return;}
  if(action==='room-next'){if(roomCode&&roomState?.hostUid===window.__onlineUID){await nextQuestion(roomCode,findNewRoomQuestion());}return;}
  if(action==='room-buzz'){if(!roomCode||!roomState||roomState.status!=='question')return;const name=roomState.players?.[window.__onlineUID]?.name||profile.name;const got=await pressBuzzer(roomCode,name);if(got)notifySound(true);else toast('Có người đã bấm chuông trước bạn.');return;}
  if(action==='room-mark'){if(roomCode&&roomState?.hostUid===window.__onlineUID&&roomState.buzz){await decide(roomCode,roomState.buzz.uid,node.dataset.correct==='1');}return;}
  if(action==='room-reveal'){if(roomCode&&roomState?.hostUid===window.__onlineUID){await showAnswer(roomCode);}return;}
 }catch(err){console.error(err);toast(err.message||'Đã xảy ra lỗi. Hãy thử lại.',true);}
});

document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.id)return;event.preventDefault();
 try{
  if(form.id==='question-form'){saveQuestion(form);return;}
  if(form.id==='profile-form'){const name=String(new FormData(form).get('name')||'').trim().slice(0,32);if(!name)return;profile.name=name;persist();render();toast('Đã cập nhật tên hiển thị.');return;}
  if(form.id==='class-setup'){const f=new FormData(form);profile.classroom=defaultClassroom();profile.classroom.players=profile.classroom.players.map((p,i)=>({...p,name:String(f.get('player-'+i)||`Thí sinh ${i+1}`).trim().slice(0,32)||p.name}));persistClass();render();toast('Đã tạo bảng thi lớp học.');return;}
  if(form.id==='create-room-form'){onlineLoading=true;render();const f=new FormData(form);const name=String(f.get('name')||profile.name).trim();const code=await createRoom(name||'MC');const user=await identity();window.__onlineUID=user.uid;onlineLoading=false;await watchOnline(code);toast(`Đã tạo phòng ${code}.`);return;}
  if(form.id==='join-room-form'){onlineLoading=true;const f=new FormData(form),code=String(f.get('code')||'').trim(),name=String(f.get('name')||profile.name).trim();const joined=await joinRoom(code,name||'Thí sinh');const user=await identity();window.__onlineUID=user.uid;onlineLoading=false;await watchOnline(joined);toast('Đã tham gia phòng.');return;}
 }catch(err){console.error(err);onlineLoading=false;roomError=err.message||'Kết nối gặp lỗi.';render();toast(roomError,true);}
});

document.addEventListener('input',event=>{const el=event.target;
 if(el.id==='bank-search'){filter.text=el.value;filter.page=0;$('#bank-results').innerHTML=libraryRows();}
 if(el.id==='setting-sound'){profile.settings.sound=el.checked;persist();toast(el.checked?'Đã bật âm thanh.':'Đã tắt âm thanh.');}
 if(el.id==='setting-motion'){profile.settings.reduceMotion=el.checked;persist();toast('Đã cập nhật cài đặt hiệu ứng.');}
 if(el.id==='star-checkbox'&&game?.mode==='olympia')game.star=el.checked;
});
document.addEventListener('change',event=>{const el=event.target;
 if(el.id==='mode-topic'){marathonTopic=el.value;}
 if(el.id==='bank-topic'){filter.topic=el.value;filter.page=0;$('#bank-results').innerHTML=libraryRows();}
 if(el.id==='bank-type'){filter.type=el.value;filter.page=0;$('#bank-results').innerHTML=libraryRows();}
 if(el.id==='class-round'){const c=profile.classroom;if(!c)return;c.round=Number(el.value);c.idx=0;c.revealed=false;c.running=false;c.seconds=c.round===3?30:c.round===2?25:20;clearInterval(classInterval);persistClass();render();}
});
$('#jsonImport').addEventListener('change',async event=>{
 const file=event.target.files?.[0];if(!file)return;
 if(window.__importKind==='bank')return importBank(file);
 try{const data=JSON.parse(await file.text());if(!data||!Array.isArray(data.history)||!Array.isArray(data.custom)||typeof data.xp!=='number')throw new Error('Đây không phải bản sao lưu dữ liệu hợp lệ.');
 if(!window.confirm('Khôi phục bản sao lưu sẽ ghi đè hồ sơ và lịch sử hiện tại. Tiếp tục?'))return;
 profile={...freshProfile(),...data};profile.settings={...freshProfile().settings,...data.settings};profile.history=data.history.slice(0,150);profile.custom=data.custom.slice(0,1500);persist();render();toast('Đã khôi phục dữ liệu từ bản sao lưu.');
 }catch(err){toast('Không thể khôi phục: '+err.message,true);}finally{event.target.value='';}
});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'&&currentModal){closeModal();return;}
 if((event.key==='/'||event.key==='k'&&event.ctrlKey)&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){event.preventDefault();navigate('library');setTimeout(()=>$('#bank-search')?.focus(),25);return;}
 if(route()==='game'&&game?.phase==='question'){
  const isInput=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
  if(event.key==='Enter'&&!(document.activeElement?.tagName==='TEXTAREA')){event.preventDefault();submitAnswer();return;}
  if(!isInput&&currentQuestion()?.type==='choice'&&['1','2','3','4'].includes(event.key)){const opts=currentQuestion().options;game.selected=opts[Number(event.key)-1];document.querySelectorAll('[data-action="option"]').forEach((b,i)=>b.classList.toggle('selected',i===Number(event.key)-1));return;}
 }
});
window.addEventListener('hashchange',()=>{mobileOpen=false;render();});
window.addEventListener('storage',e=>{if(e.key!==STORAGE)return;try{const latest=JSON.parse(e.newValue);if(latest){profile={...freshProfile(),...latest};render();}}catch{}});
window.addEventListener('beforeunload',()=>{clearInterval(quizInterval);clearInterval(classInterval);roomUnsub?.();});
if(!location.hash)history.replaceState(null,'','#/home');
render();
